INSERT INTO `sys_i18n` VALUES (491, 'ui', 'privacyPolicyPage.updateTime', '_', 'zh', '最后更新：2026-04-01', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (492, 'ui', 'privacyPolicyPage.section1Title', '_', 'zh', '1. 我们收集的信息', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (493, 'ui', 'privacyPolicyPage.section1Text', '_', 'zh', '在注册和使用服务过程中，我们会收集账号、登录信息及必要的设备信息，用于账号创建、身份校验和安全保障。', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (494, 'ui', 'privacyPolicyPage.section2Title', '_', 'zh', '2. 信息使用方式', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (495, 'ui', 'privacyPolicyPage.section2Text', '_', 'zh', '我们仅在提供产品功能、改进服务体验、保障系统安全及履行法律义务的范围内使用您的个人信息。', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (496, 'ui', 'privacyPolicyPage.section3Title', '_', 'zh', '3. 信息存储与保护', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (497, 'ui', 'privacyPolicyPage.section3Text', '_', 'zh', '我们采取访问控制、传输加密和日志审计等安全措施保护您的信息，防止未经授权访问、泄露或篡改。', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (498, 'ui', 'privacyPolicyPage.section4Title', '_', 'zh', '4. 您的权利', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (499, 'ui', 'privacyPolicyPage.section4Text', '_', 'zh', '您有权查询、更正、删除个人信息，或撤回授权同意。若需行使上述权利，请通过系统管理员或平台联系方式与我们联系。', 'admin', '2026-07-17 18:00:00', '', NULL);
