INSERT INTO `sys_i18n` VALUES (1849, 'ui', 'privacyPolicyPage.section1Title', '_', 'en', '1. Information We Collect', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (1850, 'ui', 'privacyPolicyPage.section1Text', '_', 'en', 'During registration and service usage, we collect account, sign-in, and necessary device information for account creation, identity verification, and security protection.', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (1851, 'ui', 'privacyPolicyPage.section2Title', '_', 'en', '2. How We Use Information', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (1852, 'ui', 'privacyPolicyPage.section2Text', '_', 'en', 'We use your personal information only to provide product features, improve service quality, ensure system security, and comply with legal obligations.', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (1853, 'ui', 'privacyPolicyPage.section3Title', '_', 'en', '3. Storage and Protection', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (1854, 'ui', 'privacyPolicyPage.section3Text', '_', 'en', 'We apply access control, transmission encryption, and audit logging to protect your information from unauthorized access, disclosure, or tampering.', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (1855, 'ui', 'privacyPolicyPage.section4Title', '_', 'en', '4. Your Rights', 'admin', '2026-07-17 18:00:00', '', NULL);
INSERT INTO `sys_i18n` VALUES (1856, 'ui', 'privacyPolicyPage.section4Text', '_', 'en', 'You have the right to access, correct, delete your personal information, or withdraw consent. To exercise these rights, please contact your administrator or platform support.', 'admin', '2026-07-17 18:00:00', '', NULL);
