INSERT INTO `sys_i18n` VALUES (3043, 'ui', 'system.menu.routeNameTip', '_', 'zh', '路由的唯一标识，用于路由跳转，建议使用大驼峰命名（如：UserManage）', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
