INSERT INTO `sys_i18n` VALUES (3047, 'ui', 'system.menu.componentTip', '_', 'zh', '一级父级菜单：填写 /index/index\n具体页面：填写组件路径（如 /system/user）\n目录菜单：留空', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
INSERT INTO `sys_i18n` VALUES (3048, 'ui', 'system.menu.pathTipInternal', '_', 'zh', '一级菜单：以 / 开头的绝对路径（如 /dashboard）\n二级及以下：相对路径（如 console、user）', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
INSERT INTO `sys_i18n` VALUES (3049, 'ui', 'system.menu.pathTipExternal', '_', 'zh', '外链菜单：请填写完整地址，必须以 http:// 或 https:// 开头（如 https://www.example.com）', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
INSERT INTO `sys_i18n` VALUES (3050, 'ui', 'system.menu.pathPlaceholderExternal', '_', 'zh', '如：https://www.example.com/path', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
INSERT INTO `sys_i18n` VALUES (3051, 'ui', 'system.menu.iconPlaceholder', '_', 'zh', '如：ri:user-line', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
