INSERT INTO `sys_i18n` VALUES (3053, 'ui', 'system.menu.buttonPermsPlaceholder', '_', 'zh', '如：system:user:add', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
INSERT INTO `sys_i18n` VALUES (3054, 'ui', 'system.menu.parentMenuPlaceholder', '_', 'en', 'Select parent menu, or leave empty for top level', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
