INSERT INTO `sys_i18n` VALUES (3056, 'ui', 'system.menu.routeNameTip', '_', 'en', 'Unique route identifier for navigation. Prefer PascalCase (e.g. UserManage).', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
INSERT INTO `sys_i18n` VALUES (3057, 'ui', 'system.menu.routeNamePlaceholder', '_', 'en', 'e.g. UserManage', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
