INSERT INTO `sys_i18n` VALUES (3060, 'ui', 'system.menu.componentTip', '_', 'en', 'Top-level parent: /index/index\nPage menu: component path (e.g. /system/user)\nDirectory: leave empty', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
INSERT INTO `sys_i18n` VALUES (3061, 'ui', 'system.menu.pathTipInternal', '_', 'en', 'Top-level: absolute path starting with / (e.g. /dashboard)\nNested: relative path (e.g. console, user)', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
INSERT INTO `sys_i18n` VALUES (3062, 'ui', 'system.menu.pathTipExternal', '_', 'en', 'External menu: full URL starting with http:// or https:// (e.g. https://www.example.com)', 'admin', '2026-07-17 20:06:43', '', '2026-07-17 20:39:55');
