DROP TABLE IF EXISTS `sys_i18n`;
CREATE TABLE `sys_i18n`  (
  `i18n_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '翻译ID',
  `namespace` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '命名空间（menu/dict_data/ui）',
  `resource_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源键（菜单为 menuId）',
  `field_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'menu_name' COMMENT '字段名',
  `lang` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '语言编码',
  `content` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '译文',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`i18n_id`) USING BTREE,
  UNIQUE INDEX `uk_i18n`(`namespace`, `resource_key`, `field_name`, `lang`) USING BTREE,
  INDEX `idx_ns_lang`(`namespace`, `lang`) USING BTREE,
  INDEX `idx_ns_key`(`namespace`, `resource_key`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3041 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '通用国际化翻译表' ROW_FORMAT = Dynamic;

